  "Alla börjar i en rostig husvagn ute i förorten. Tjäna pengar på stadens jobb, köp mat så du orkar, klä dig snyggt – och spara ihop till en bättre bostad hos bostadsbyrån!": "Semua orang mulai di karavan berkarat di pinggiran kota. Cari uang dari pekerjaan di kota, beli makanan supaya kuat, berpakaian keren – dan menabung untuk rumah yang lebih baik di agen properti!",
