  "Alla fyra livsmålen på <b>{0} dagar</b> – från en rostig husvagn till ett riktigt liv!": "Keempat tujuan hidup dalam <b>{0} hari</b> – dari karavan berkarat ke hidup yang sesungguhnya!",
