  "Du får den i handen och sätter dig vid bistroborden här bredvid – mättheten kommer medan du äter.": "Kamu pegang makanannya dan duduk di meja bistro di sebelah sini. Kenyangnya datang sambil kamu makan.",
  "Du får en bricka och sätter dig vid ett ledigt bord. Mättnaden och energin kommer medan du äter – bara när du sitter!": "Kamu dapat nampan dan duduk di meja yang kosong. Kenyang dan energi bertambah sambil kamu makan – hanya saat duduk!",
  "Du får maten på en bricka och sätter dig vid ett bord eller i fönstret med utsikt över havet. Mättnaden och energin kommer medan du äter – och när allt är uppätet blir du gladare!": "Makananmu datang di atas nampan, lalu kamu duduk di meja atau di jendela dengan pemandangan laut. Kenyang dan energi bertambah sambil makan – dan kalau semua habis, kamu jadi lebih senang!",
  "Du får maten på en bricka och sätter dig vid ett ledigt bord eller vid fönstret. Mättnaden och energin kommer medan du äter – bara när du sitter!": "Makananmu diberikan di nampan, lalu kamu duduk di meja kosong atau di dekat jendela. Kenyang dan energi datang sambil makan – hanya saat kamu duduk!",
