  "Kronan på kattstatyn i Tassbacken har försvunnit. Ett nytt kapitel varje dag – kan du lösa mysteriet?": "Mahkota di patung kucing di Bukit Tapak hilang. Bab baru setiap hari – bisakah kamu memecahkan misterinya?",
