  "Välj en bok. Att läsa ut den tar en timme och ger en utbildningspoäng första gången.": "Pilih buku. Membacanya sampai selesai butuh satu jam dan memberi satu poin pendidikan untuk pertama kali.",
  "Välj en fröpåse. Vattna bädden varje dag – två dagar utan vatten och plantorna vissnar. Skörden hamnar i skafferiet.": "Pilih kantong benih. Siram bedengnya tiap hari – dua hari tanpa air, tanamannya layu. Hasil panen masuk ke lemari dapur.",
  "Välj en häst.": "Pilih seekor kuda.",
  "Välj en låt – den går hemma tills du stänger av eller lägger dig. Alla låtar i Pixelstaden finns här.": "Pilih lagu – lagunya terus diputar di rumah sampai kamu matikan atau tidur. Semua lagu di Kota Pixel ada di sini.",
  "Välj en möbel först": "Pilih perabot dulu",
  "Välj en ny frisyr eller färg först.": "Pilih dulu gaya rambut atau warna baru.",
  "Välj en ny frisyr eller hårfärg – förhandsbilden visar hur det blir på dig.": "Pilih gaya rambut atau warna baru – pratinjau menunjukkan hasilnya padamu.",
  "Välj ett belopp.": "Pilih jumlahnya.",
  "Välj ett märke": "Pilih tempelan",
  "Välj ett ställe på kartan.": "Pilih tempat di peta.",
  "Välj färg – en ballong kostar {0}. Den följer med dig på tivolit hela dagen!": "Pilih warna – satu balon harganya {0}. Balonnya ikut kamu seharian di taman hiburan!",
  "Välj hur högt du siktar i varje mål. Du har klarat livet i Pixelstaden när alla fyra är nådda samtidigt.": "Pilih seberapa tinggi bidikanmu di tiap tujuan. Kamu menaklukkan hidup di Kota Pixel kalau keempatnya tercapai bersamaan.",
  "Välj hur mycket du vill sätta in.": "Pilih berapa yang mau kamu setor.",
  "Välj hur mycket du vill ta ut.": "Pilih berapa yang mau kamu tarik.",
  "Välj kana. Trapporna upp är branta – håll i räcket.": "Pilih seluncuran. Tangganya curam – pegang pegangannya.",
  "Välj någon i laget – eller skriv ett eget förnamn och nummer.": "Pilih seseorang di tim – atau tulis nama depan dan nomor sendiri.",
  "Välj något från menyn först!": "Pilih dari menu dulu!",
  "Välj något i butiken så slår jag in det!": "Pilih barang di toko, nanti kuhitung di kasir!",
  "Välkommen fram!": "Selamat sampai tujuan!",
  "Välkommen in! Värm upp lite först så går lyften lättare.": "Selamat datang! Pemanasan dulu sedikit supaya angkatannya lebih ringan.",
  "Välkommen in! ✨": "Selamat datang! ✨",
  "Välkommen ombord! Vad får det lov att vara?": "Selamat datang di kapal! Mau pesan apa?",
  "Välkommen till BLIXT!": "Selamat datang di KILAT!",
  "Välkommen till Biblioteket! Ta en bok från hyllan och sätt dig vid ett bord. Varje utläst bok ger en utbildningspoäng.": "Selamat datang di Perpustakaan! Ambil buku dari rak dan duduklah di meja. Setiap buku yang selesai dibaca memberi satu poin pendidikan.",
  "Välkommen till Bio Pixel!": "Selamat datang di Pixel 21!",
  "Välkommen till Gamla stan! Huset bakom mig är från 1699 – titta på årtalet i gaveln.": "Selamat datang di Kota Tua! Rumah di belakangku dari tahun 1699 – lihat angka tahunnya di atap.",
  "Välkommen till Klipp & Klo! Har du ett husdjur så gör vi det jättefint här. ✂️": "Selamat datang di Cukur & Cakar! Kalau kamu punya hewan peliharaan, di sini kami buat dia cantik sekali. ✂️",
  "Välkommen till Klipp & Klo! ✂️ Klicka på trimbordet så fixar vi ditt djur.": "Selamat datang di Cukur & Cakar! ✂️ Klik meja grooming, nanti hewanmu kami rapikan.",
  "Välkommen till Kurr! ☕ Fika vid disken – och klappa gärna katterna, de älskar det.": "Selamat datang di Meong! ☕ Pesan camilan di kasir – dan elus kucing-kucingnya, mereka suka sekali.",
  "Välkommen till Museet! Titta på föremålen – skyltarna berättar. När du sett tre stycken får du ta quizet hos mig.": "Selamat datang di Museum! Lihat benda-bendanya – papan keterangannya bercerita. Setelah kamu melihat tiga, kamu boleh ikut kuis denganku.",
  "Välkommen till Pixel Gym! Hantlarna och boxsäcken ger STYRKA, gruppasset KONDITION och dansgolvet RYTM.": "Selamat datang di Pixel Gym! Barbel dan samsak melatih KEKUATAN, kelas senam melatih STAMINA, dan lantai dansa melatih IRAMA.",
  "Välkommen till Pixelbanken!": "Selamat datang di Bank Pixel!",
  "Välkommen till frisören! Sätt dig i en ledig stol, så fixar vi håret. 💇": "Selamat datang di salon! Duduk di kursi kosong, kita rapikan rambutmu. 💇",
  "Välkommen till kassan.": "Selamat datang di loket.",
  "Välkommen till utställningen! Anmäl ditt djur här vid disken – det kostar 100 kr.": "Selamat datang di kontes! Daftarkan hewanmu di meja ini – biayanya Rp 100.",
  "Välkommen till {0}! Första föreläsningen är i Aula 1 – sätt dig i en ledig bänk.": "Selamat datang di {0}! Kuliah pertama di Aula 1 – duduklah di bangku kosong.",
  "Välkommen tillbaka!": "Selamat datang kembali!",
  "Välkommen tillbaka! Allt rullar som det ska? 🔧": "Selamat datang kembali! Semua masih lancar? 🔧",
  "Välkommen upp! ⚽ Laget står där borta – klicka på en spelare så provar du matchstället.": "Selamat datang di atas! ⚽ Timnya berdiri di sana – klik seorang pemain untuk mencoba seragamnya.",
  "Välkommen!": "Selamat datang!",
  "Välkommen! Ditt sparkonto växer med {0} % i veckan.": "Selamat datang! Tabunganmu tumbuh {0} % per minggu.",
  "Välkommen! Entrén kostar <b>{0}</b> och gäller hela dagen. Lejonen, elefanterna, girafferna, pingvinerna, klappzoo och ponnyridningen väntar där inne.": "Selamat datang! Tiket masuk <b>{0}</b> dan berlaku seharian. Singa, gajah, jerapah, penguin, zona elus, dan kuda poni menunggu di dalam.",
  "Välkommen! Något nytt i dag?": "Selamat datang! Mau gaya baru hari ini?",
  "Välkommen! Ska vi prata sparande?": "Selamat datang! Mau ngobrol soal menabung?",
  "Välkommen! Tentorna skrivs vid tentabordet, lånen här.": "Selamat datang! Ujian dikerjakan di meja ujian, pinjam buku di sini.",
  "Välkommen! Vad blir det?": "Selamat datang! Mau pesan apa?",
