  "🏔️ Härifrån ser du Pixelstaden, havet och fyren på Solön. På riktigt klara dagar – Pixelberg.": "🏔️ Dari sini kamu bisa melihat Kota Pixel, laut, dan mercusuar Pulau Surya. Kalau cuaca benar-benar cerah – Gunung Pixel.",
  "🏔️ Toppen! Hela Pixelstaden ligger där nere.": "🏔️ Puncak! Seluruh Kota Pixel ada di bawah sana.",
