  "🏗️ Hamnkranen lyfter 20 ton. Kranföraren Berit har lyft 11 000 containrar och tappat noll.": "🏗️ Derek pelabuhan mengangkat 20 ton. Operatornya, Bu Ratih, sudah mengangkat 11.000 kontainer dan tidak pernah menjatuhkan satu pun.",
  "🏙️ Glasskyskrapor ända upp i himlen. Finanskvarteret!": "🏙️ Gedung kaca menjulang sampai langit. Kawasan Bisnis!",
  "🏙️ Höga hus så långt man ser. Här jobbar alla med slips.": "🏙️ Gedung tinggi sejauh mata memandang. Di sini semua kerja pakai dasi.",
  "🏙️ Höga hus överallt – och där borta ett gammalt stenhus mitt emellan.": "🏙️ Gedung tinggi di mana-mana – dan di sana ada rumah batu tua di tengahnya.",
  "🏙️ Skyskraporna i finanskvarteret. Börsen rullar på tornet mitt emot.": "🏙️ Gedung pencakar langit di Kawasan Bisnis. Harga saham bergulir di menara seberang.",
